const input = $input.first().json;
const component = $('Restore Component Input').first().json;

const progress = input.reProgress || {};

let failedStage = 'UNKNOWN';

if (!progress.workspacePrepared) {
  failedStage = 'PREPARE_WORKSPACE';
} else if (!progress.sdsScanCompleted) {
  failedStage = 'SDS_SCAN';
} else if (!progress.sdsGenerated) {
  failedStage = 'SDS_GENERATE';
} else if (!progress.srsScanCompleted) {
  failedStage = 'SRS_SCAN';
} else if (!progress.srsGenerated) {
  failedStage = 'SRS_GENERATE';
} else if (!progress.brsScanCompleted) {
  failedStage = 'BRS_SCAN';
} else if (!progress.brsGenerated) {
  failedStage = 'BRS_GENERATE';
}

const errorMessage =
  input.error?.message ||
  input.message ||
  `${failedStage} did not complete successfully`;

return [{
  json: {
    trackerId: component.trackerId,
    auditId: component.auditId,
    componentName: component.componentName,
    status: 'FAILED',
    failed_stage: failedStage,
    error_message: errorMessage,
    finished_at: new Date().toISOString()
  }
}];

const errorItem = $input.first().json;

const component = $('Restore Component Input').first().json;

const message =
  errorItem.error?.message ||
  errorItem.message ||
  'GitHub PUT File failed';

const filePath =
  $('Prepare Upsert Payload1').first().json.filePath ||
  'unknown';

return [{
  json: {
    trackerId: component.trackerId,
    auditId: component.auditId,
    componentName: component.componentName,

    status: 'FAILED',
    failed_stage: 'GITHUB_PUT_FILE',
    last_stage: 'GITHUB_PUT_FILE',

    error_message: `File: ${filePath} | Error: ${message}`,
    finished_at: new Date().toISOString()
  }
}];

const existingFile = $json;

// Loop Over Items'taki mevcut doküman
const source = $('Loop Over Documents').item.json;

if (!source) {
  throw new Error('Source document could not be resolved');
}

if (!source.documentType) {
  throw new Error('documentType missing');
}

if (!source.content || !source.content.trim()) {
  throw new Error(
    `${source.documentType} content is missing or empty`
  );
}

if (!source.filePath) {
  throw new Error(
    `${source.documentType} filePath is missing`
  );
}


// --------------------------------------------------
// GitHub'da dosya mevcut mu?
// --------------------------------------------------

const fileExists =
  existingFile.statusCode === 200 &&
  existingFile.body &&
  existingFile.body.sha;


// --------------------------------------------------
// GitHub PUT body
// --------------------------------------------------

const payload = {
  message:
    `docs: update ${source.documentType} reference`,

  content:
    Buffer
      .from(source.content, 'utf8')
      .toString('base64'),

  branch:
    source.branch
};


// Dosya zaten varsa update için SHA zorunlu
if (fileExists) {
  payload.sha = existingFile.body.sha;
}


// --------------------------------------------------
// Output
// --------------------------------------------------

return {
  json: {
    ...source,

    fileExists,

    existingSha:
      fileExists
        ? existingFile.body.sha
        : null,

    commitMessage:
      payload.message,

    githubPayload:
      payload
  }
};

const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const input = $input.first().json;
const workspace = input.reWorkspace || {};

const FRAMEWORK = workspace.brsFrameworkPath;
const OUTPUT = workspace.brsOutputPath;
const MODEL = workspace.ollamaModel;

function log(stage, message) {
  console.log(
    `[${new Date().toISOString()}] [BRS-GENERATE] [${stage}] ${message}`
  );
}

function listMarkdown(root) {
  const files = [];

  function walk(dir) {
    for (const entry of fs.readdirSync(dir, {
      withFileTypes: true
    })) {
      const full = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        walk(full);
      } else if (
        entry.isFile() &&
        entry.name.toLowerCase().endsWith('.md')
      ) {
        files.push(path.relative(root, full));
      }
    }
  }

  walk(root);
  return files;
}


function selectDocument(files) {
  const normalized = files.map(file => ({
    original: file,
    relative: file.replace(/\\/g, '/').toLowerCase(),
    name: path.basename(file).toLowerCase()
  }));

  const finalCandidates = normalized.filter(item =>
    item.relative.split('/').includes('final') &&
    /^brs(?:-re|-document|-final|-master|-complete)?\.md$/.test(item.name)
  );

  if (finalCandidates.length === 1) {
    return finalCandidates[0].original;
  }

  if (finalCandidates.length > 1) {
    throw new Error(
      'Multiple BRS final documents: ' +
      JSON.stringify(finalCandidates.map(x => x.original))
    );
  }

  const priority = [
    'brs-re-document.md',
    'brs.md',
    'brs-final.md',
    'brs-master.md',
    'brs-re.md',
    'brs-re-complete.md',
    'brs-complete.md'
  ];

  for (const expected of priority) {
    const matches = normalized.filter(item =>
      item.name === expected &&
      !item.relative.split('/').includes('sections')
    );

    if (matches.length === 1) return matches[0].original;

    if (matches.length > 1) {
      throw new Error(`Multiple BRS candidates: ${expected}`);
    }
  }

  const candidates = normalized.filter(item => {
    const name = item.name;
    const parts = item.relative.split('/');

    if (parts.includes('sections')) return false;
    if (/^(section-|\d{2}-)/.test(name)) return false;

    const excluded = [
      'manifest', 'report', 'summary', 'scan',
      'quality', 'handoff', 'boundary',
      'code-structure', 'project-context',
      'tracker', 'progress'
    ];

    if (excluded.some(word => name.includes(word))) {
      return false;
    }

    return name.startsWith('brs');
  });

  if (candidates.length === 1) {
    return candidates[0].original;
  }

  throw new Error(
    'BRS final document could not be identified: ' +
    JSON.stringify({
      candidates: candidates.map(x => x.original),
      allFiles: files
    })
  );
}

function runGeneration() {
  return new Promise((resolve, reject) => {
    const started = Date.now();
    let settled = false;

    const child = spawn('opencode', [
      'run',
      '--continue',
      '/generate-re-brs --interactive=false',
      '--agent',
      'brs-re-lead-agent',
      '--model',
      `ollama-cloud/${MODEL}`
    ], {
      cwd: FRAMEWORK,
      stdio: ['ignore', 'pipe', 'pipe']
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', data => {
      const text = data.toString();
      stdout += text;
      console.log(text);
    });

    child.stderr.on('data', data => {
      const text = data.toString();
      stderr += text;
      console.log(text);
    });

    child.on('error', error => {
      if (settled) return;
      settled = true;
      error.stdout = stdout;
      error.stderr = stderr;
      reject(error);
    });

    child.on('close', code => {
      if (settled) return;
      settled = true;

      if (code !== 0) {
        const error = new Error(
          `BRS generation failed: exit code ${code}`
        );
        error.stdout = stdout;
        error.stderr = stderr;
        reject(error);
        return;
      }

      resolve({
        durationSeconds: Number(
          ((Date.now() - started) / 1000).toFixed(1)
        )
      });
    });
  });
}

try {
  if (input.status === 'failed') {
    throw new Error(
      `Previous stage failed: ${input.stage}: ${input.error}`
    );
  }

  if (!FRAMEWORK || !fs.existsSync(FRAMEWORK)) {
    throw new Error('BRS framework path missing');
  }

  if (!OUTPUT || !fs.existsSync(OUTPUT)) {
    throw new Error('BRS output path missing');
  }

  if (!MODEL) throw new Error('Ollama model missing');

  if (input.reProgress?.brsScanCompleted !== true) {
    throw new Error('BRS scan not completed');
  }

  const started = Date.now();

  const before = new Map(
    listMarkdown(OUTPUT).map(file => {
      const stat = fs.statSync(path.join(OUTPUT, file));
      return [file, `${stat.size}:${stat.mtimeMs}`];
    })
  );

  log('GENERATE', 'Starting BRS generation');

  const generation = await runGeneration();

  const markdownFiles = listMarkdown(OUTPUT);

  const selectedSourceFile = selectDocument(markdownFiles);
  const sourcePath = path.join(OUTPUT, selectedSourceFile);
  const stat = fs.statSync(sourcePath);

  if (!stat.isFile() || stat.size === 0) {
    throw new Error('BRS final document is missing or empty');
  }

  const documentWasUpdated =
    before.get(selectedSourceFile) !==
    `${stat.size}:${stat.mtimeMs}`;

  log(
    'VALIDATE',
    `Selected=${selectedSourceFile}, updated=${documentWasUpdated}`
  );

  const content = fs.readFileSync(sourcePath, 'utf8');

  if (!content.trim()) {
    throw new Error('BRS final document is empty');
  }

  const finalDocumentPath = path.join(
    OUTPUT,
    'brs-final.md'
  );

  if (path.resolve(sourcePath) !== path.resolve(finalDocumentPath)) {
    fs.copyFileSync(sourcePath, finalDocumentPath);
  }

  const totalDurationSeconds = Number(
    ((Date.now() - started) / 1000).toFixed(1)
  );

  log('DONE', `Selected: ${selectedSourceFile}`);

  return [{
    json: {
      ...input,
      status: 'success',
      stage: 'brs-generate',
      error: null,
      reProgress: {
        ...(input.reProgress || {}),
        brsGenerated: true
      },
      brsResult: {
        status: 'success',
        generationDurationSeconds: generation.durationSeconds,
        totalDurationSeconds,
        outputPath: OUTPUT,
        markdownFiles,
        selectedSourceFile,
        finalDocumentPath
      }
    }
  }];

} catch (error) {
  log('FAILED', error.message);

  return [{
    json: {
      ...input,
      status: 'failed',
      stage: 'brs-generate',
      error: error.message,
      stderr: error.stderr || null,
      stdout: error.stdout || null,
      reProgress: {
        ...(input.reProgress || {}),
        brsGenerated: false
      },
      brsResult: {
        status: 'failed',
        error: error.message

      }
    }
  }];
}

const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const input = $json || {};
const workspace = input.reWorkspace || {};

const COMPONENT_CHECKOUT_PATH = workspace.componentCheckoutPath;
const SRS_OUTPUT = workspace.srsOutputPath;
const BRS_FRAMEWORK_PATH = workspace.brsFrameworkPath;
const OLLAMA_MODEL = workspace.ollamaModel;

if (!COMPONENT_CHECKOUT_PATH) throw new Error('componentCheckoutPath missing');
if (!SRS_OUTPUT) throw new Error('srsOutputPath missing');
if (!BRS_FRAMEWORK_PATH) throw new Error('brsFrameworkPath missing');
if (!OLLAMA_MODEL) throw new Error('ollamaModel missing');

const RUNNER_WORK = path.join(BRS_FRAMEWORK_PATH, '.runner-work');
const RUNNER_COMPONENT_SOURCE = path.join(RUNNER_WORK, 'component-source');
const RUNNER_SRS_OUTPUT = path.join(RUNNER_WORK, 'srs-output');
const BRS_OUTPUT = path.join(RUNNER_WORK, 'brs-output');

function log(stage, message) {
  console.log(
    `[${new Date().toISOString()}] [BRS-SCAN] [${stage}] ${message}`
  );
}

async function runCommand(label, command, cwd) {
  return new Promise((resolve, reject) => {
    const start = Date.now();

    log(label, 'START');

    const child = spawn('/bin/sh', ['-c', command], {
      cwd,
      stdio: ['ignore', 'pipe', 'pipe']
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', data => {
      const text = data.toString();
      stdout += text;

      for (const line of text.split('\n')) {
        if (line.trim()) log(label, `OUT: ${line}`);
      }
    });

    child.stderr.on('data', data => {
      const text = data.toString();
      stderr += text;

      for (const line of text.split('\n')) {
        if (line.trim()) log(label, `ERR: ${line}`);
      }
    });

    child.on('error', error => {
      error.stdout = stdout;
      error.stderr = stderr;
      reject(error);
    });

    child.on('close', code => {
      const duration = ((Date.now() - start) / 1000).toFixed(1);

      log(label, `END code=${code} duration=${duration}s`);

      if (code === 0) {
        resolve({
          stdout,
          stderr,
          durationSeconds: Number(duration)
        });
        return;
      }

      const error = new Error(`${label} failed with exit code ${code}`);
      error.stdout = stdout;
      error.stderr = stderr;
      reject(error);
    });
  });
}

try {
  const nodeStart = Date.now();

  log('1/4', 'Validating component source and SRS output');

  if (!fs.existsSync(COMPONENT_CHECKOUT_PATH)) {
    throw new Error(`Component source not found: ${COMPONENT_CHECKOUT_PATH}`);
  }

  if (!fs.existsSync(SRS_OUTPUT)) {
    throw new Error(`SRS output not found: ${SRS_OUTPUT}`);
  }

  if (!fs.existsSync(BRS_FRAMEWORK_PATH)) {
    throw new Error(`BRS framework not found: ${BRS_FRAMEWORK_PATH}`);
  }

  log('1/4', 'Inputs OK');

  log('2/4', 'Preparing BRS runner workspace');

  fs.rmSync(RUNNER_WORK, {
    recursive: true,
    force: true
  });

  fs.mkdirSync(RUNNER_WORK, {
    recursive: true
  });

  await runCommand(
    'COPY-SOURCE',
    `cp -R "${COMPONENT_CHECKOUT_PATH}" "${RUNNER_COMPONENT_SOURCE}"`,
    BRS_FRAMEWORK_PATH
  );

  await runCommand(
    'COPY-SRS',
    `cp -R "${SRS_OUTPUT}" "${RUNNER_SRS_OUTPUT}"`,
    BRS_FRAMEWORK_PATH
  );

  log('2/4', 'Component source and SRS copied');

  log('3/4', 'Starting BRS /scan-source');

  const scanResult = await runCommand(
    'SCAN-SOURCE',

    `opencode run ` +
    `"/scan-source --path .runner-work/component-source ` +
    `--srs-output .runner-work/srs-output ` +
    `--output .runner-work/brs-output" ` +
    `--agent brs-re-lead-agent ` +
    `--model "ollama-cloud/${OLLAMA_MODEL}"`,

    BRS_FRAMEWORK_PATH
  );

  log(
    '3/4',
    `BRS source scan completed in ${scanResult.durationSeconds}s`
  );

  log('4/4', 'Checking BRS scan output');

  if (!fs.existsSync(BRS_OUTPUT)) {
    throw new Error(`BRS output directory not created: ${BRS_OUTPUT}`);
  }

  const totalDuration =
    ((Date.now() - nodeStart) / 1000).toFixed(1);

  log('DONE', `BRS scan completed successfully in ${totalDuration}s`);

  return [{
    json: {
      ...input,

      reWorkspace: {
        ...workspace,
        brsRunnerWork: RUNNER_WORK,
        brsOutputPath: BRS_OUTPUT
      },

      reProgress: {
        ...(input.reProgress || {}),
        brsScanCompleted: true,
        brsGenerated: false
      },

      brsScanResult: {
        status: 'success',
        durationSeconds: Number(totalDuration)
      }
    }
  }];

} catch (error) {
  log('FAILED', error.message);

  return [{
    json: {
      ...input,
      status: 'failed',
      stage: 'brs-scan',
      error: error.message || null,
      stderr: error.stderr || null,
      stdout: error.stdout || null,

      reProgress: {
        ...(input.reProgress || {}),
        brsScanCompleted: false
      }
    }
  }];
}

