const FRAMEWORK = workspace.sdsFrameworkPath;
const OUTPUT = workspace.sdsOutputPath;
const MODEL = workspace.ollamaModel;

function log(stage, message) {
  console.log(
    `[${new Date().toISOString()}] [SDS-GENERATE] [${stage}] ${message}`
  );
}

function listMarkdown(root) {
  const files = [];

  function walk(dir) {
    for (const entry of fs.readdirSync(dir, {
      withFileTypes: true
    })) {
      const full = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        walk(full);
      } else if (
        entry.isFile() &&
        entry.name.toLowerCase().endsWith('.md')
      ) {
        files.push(path.relative(root, full));
      }
    }
  }

  walk(root);
  return files;
}


function selectDocument(files) {
  const normalized = files.map(file => ({
    original: file,
    relative: file.replace(/\\/g, '/').toLowerCase(),
    name: path.basename(file).toLowerCase()
  }));

  // 1. Öncelik: final/ klasöründeki gerçek SDS adayları
  const finalFolderCandidates = normalized.filter(item =>
    item.relative.split('/').includes('final') &&
    /^sds(?:-re|-document|-final|-master|-complete)?\.md$/.test(item.name)
  );

  if (finalFolderCandidates.length === 1) {
    return finalFolderCandidates[0].original;
  }

  if (finalFolderCandidates.length > 1) {
    throw new Error(
      'Multiple SDS documents in final folder: ' +
      JSON.stringify(finalFolderCandidates.map(x => x.original))
    );
  }

  // 2. Öncelik: Bilinen nihai dosya isimleri
  const priority = [
    'sds-re-document.md',
    'sds.md',
    'sds-final.md',
    'sds-master.md',
    'sds-re.md',
    'sds-re-complete.md',
    'sds-complete.md'
  ];

  for (const expected of priority) {
    const matches = normalized.filter(item =>
      item.name === expected &&
      !item.relative.split('/').includes('sections')
    );

    if (matches.length === 1) {
      return matches[0].original;
    }

    if (matches.length > 1) {
      throw new Error(
        `Multiple SDS candidates: ${expected}`
      );
    }
  }

  // 3. Öncelik: Yardımcı dosyaları ele
  const candidates = normalized.filter(item => {
    const name = item.name;
    const parts = item.relative.split('/');

    if (parts.includes('sections')) return false;

    if (/^(section-|\d{2}-)/.test(name)) return false;

    const excluded = [
      'manifest',
      'report',
      'summary',
      'scan',
      'quality',
      'handoff',
      'boundary',
      'code-structure',
      'project-context',
      'tracker',
      'progress'
    ];

    if (excluded.some(word => name.includes(word))) {
      return false;
    }

    return name.startsWith('sds');
  });

  if (candidates.length === 1) {
    return candidates[0].original;
  }

  throw new Error(
    'SDS final document could not be identified. ' +
    JSON.stringify({
      candidates: candidates.map(x => x.original),
      allFiles: files
    })
  );
}


function runGeneration() {
  return new Promise((resolve, reject) => {
    const started = Date.now();
    let settled = false;

    const child = spawn('opencode', [
      'run',
      '--continue',
      '/generate-re-sds --interactive=false',
      '--agent',
      'sds-re-lead-agent',
      '--model',
      `ollama-cloud/${MODEL}`
    ], {
      cwd: FRAMEWORK,
      stdio: ['ignore', 'pipe', 'pipe']
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', data => {
      const text = data.toString();
      stdout += text;
      console.log(text);
    });

    child.stderr.on('data', data => {
      const text = data.toString();
      stderr += text;
      console.log(text);
    });

    child.on('error', error => {
      if (settled) return;
      settled = true;
      error.stdout = stdout;
      error.stderr = stderr;
      reject(error);
    });

    child.on('close', code => {
      if (settled) return;
      settled = true;

      if (code !== 0) {
        const error = new Error(
          `SDS generation failed: exit code ${code}`
        );
        error.stdout = stdout;
        error.stderr = stderr;
        reject(error);
        return;
      }

      resolve({
        durationSeconds: Number(
          ((Date.now() - started) / 1000).toFixed(1)
        )
      });
    });
  });
}

