      const stat = fs.statSync(path.join(OUTPUT, file));
      return [file, `${stat.size}:${stat.mtimeMs}`];
    })
  );

  log('GENERATE', 'Starting SDS generation');

  const generation = await runGeneration();

  const markdownFiles = listMarkdown(OUTPUT);

  const selectedSourceFile = selectDocument(markdownFiles);
  const sourcePath = path.join(OUTPUT, selectedSourceFile);

