  if (!stat.isFile() || stat.size === 0) {
    throw new Error('SDS final document is missing or empty');
  }

  const documentWasUpdated =
    before.get(selectedSourceFile) !==
    `${stat.size}:${stat.mtimeMs}`;

  log(
