  );

  const content = fs.readFileSync(sourcePath, 'utf8');

  if (!content.trim()) {
    throw new Error('SDS final document is empty');
  }

  const finalDocumentPath = path.join(
    OUTPUT,
    'sds-final.md'
  );

  if (path.resolve(sourcePath) !== path.resolve(finalDocumentPath)) {
    fs.copyFileSync(sourcePath, finalDocumentPath);
  }

  const totalDurationSeconds = Number(
    ((Date.now() - started) / 1000).toFixed(1)
  );

  log('DONE', `Selected: ${selectedSourceFile}`);

  return [{
