// COMMAND RUNNER
// ============================================================

async function runCommand(command, workingDir = ROOT_DIR) {

  return new Promise((resolve, reject) => {

    console.log(`[START] ${command}`);

    const child = spawn(
      '/bin/sh',
      ['-c', command],
      {
        cwd: workingDir,
        stdio: ['ignore', 'pipe', 'pipe']
      }
    );

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (data) => {

      const text = data.toString();

      stdout += text;

      console.log(`[STDOUT] ${text.trim()}`);

    });

    child.stderr.on('data', (data) => {

      const text = data.toString();

      stderr += text;

      console.log(`[STDERR] ${text.trim()}`);

    });

    child.on('error', (error) => {

      error.stdout = stdout;
      error.stderr = stderr;

      reject(error);

    });

    child.on('close', (code) => {

      console.log(`[END] Exit code: ${code}`);

      if (code === 0) {

        resolve(stdout);

        return;

      }

      const error =
        new Error(`Command failed with exit code ${code}`);

      error.stdout = stdout;
      error.stderr = stderr;

      reject(error);

    });

  });

}


// ============================================================
// AUTH HEADER
// ============================================================

function gitAuthHeader(token) {

  const basic = Buffer
    .from(`x-access-token:${token}`)
    .toString('base64');

  return `Authorization: Basic ${basic}`;

}


// ============================================================
// SECRET REDACTION
// ============================================================

function redactSecrets(value) {

  if (!value) return value;

  let result = String(value);

  const secrets = [
    COMPONENT_REPO_TOKEN,
    COGNIA_REPO_TOKEN,
    OLLAMA_API_KEY
  ];

  for (const secret of secrets) {

    if (!secret) continue;

    result =
      result.split(secret).join('[REDACTED]');

    const encoded =
      Buffer
        .from(`x-access-token:${secret}`)
        .toString('base64');

    result =
      result.split(encoded).join('[REDACTED]');

  }

  return result;

}


